<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class StoreTransportServiceRequest extends FormRequest{public function authorize():bool{return$this->user()?->can('transporte.servicios.crear')??false;}public function rules():array{$c=$this->user()->company_id;return['transport_route_id'=>['required',Rule::exists('transport_routes','id')->where(fn($q)=>$q->where('company_id',$c)->where('status','active'))],'service_type'=>['required',Rule::in(array_keys(config('transport.service_types')))],'shift'=>['required',Rule::in(array_keys(config('transport.shifts')))],'scheduled_start_at'=>'required|date','scheduled_arrival_at'=>'required|date|after:scheduled_start_at','planned_vehicle_id'=>['required',Rule::exists('transport_vehicles','id')->where(fn($q)=>$q->where('company_id',$c)->where('status','active'))],'planned_driver_id'=>['required',Rule::exists('transport_personnel','id')->where(fn($q)=>$q->where('company_id',$c)->where('status','active')->where('is_driver',1))],'planned_monitor_id'=>['nullable',Rule::exists('transport_personnel','id')->where(fn($q)=>$q->where('company_id',$c)->where('status','active')->where('is_monitor',1))],'notes'=>'nullable|string|max:2000'];}}
